function draw(input){
 const {board,width,height,params}=input;const P=VisualBook.palette;const a=params.a,b=params.b;const g=[2*a,4*b];const mobile=width<600;const left=mobile?(width-190)/2:46,top=65,size=mobile?190:280;const right=left+size,bottom=top+size;
 board.text('model','f = x₁² + 2x₂²',mobile?24:370,24,{size:16,color:P.ink});
 const F=board.axes('plane',{xDomain:[-2,2],yDomain:[-2,2],equalUnits:true,box:[left,top,right,bottom],grid:true});
 for(let j=1;j<=4;j++){const level=j;const points=[];for(let k=0;k<=120;k++){let t=k/120*Math.PI*2;points.push([Math.sqrt(level)*Math.cos(t),Math.sqrt(level/2)*Math.sin(t)]);}board.curve('contour-'+j,F,points,{color:P.faint,width:1});}
 board.line('fix-x2',F.x(-2),F.y(b),F.x(2),F.y(b),P.blue,1.5,0.65);
 board.line('fix-x1',F.x(a),F.y(-2),F.x(a),F.y(2),P.orange,1.5,0.65);
 board.vector('gradient',F,[a,b],[a+g[0],b+g[1]],{color:P.ink,label:'∇f'});
 board.circle('point',F.x(a),F.y(b),4,P.ink);
 board.text('plane-x','x₁',right+18,bottom-8,{size:14,color:P.muted});board.text('plane-y','x₂',left-16,top-18,{size:14,color:P.muted});
 const sx=mobile?38:370,sw=mobile?width-76:width-sx-28;const sy=mobile?bottom+45:85;const sh=mobile?65:90;
 function slice(id,y,coeff,color,label,slope,at){board.text(id+'-label',label,sx,y-14,{size:14,color});const frame=board.axes(id+'-axes',{xDomain:[-1,1],yDomain:[-2,3],box:[sx,y,sx+sw,y+sh],grid:false});let fun=VisualBook.scalarFunction({kind:'polynomial',coefficients:coeff});const pts=[];for(let i=0;i<=80;i++){let x=-1+2*i/80;pts.push([x,fun.f(x)]);}board.curve(id+'-curve',frame,pts,{color,width:2});const v=fun.f(at);board.curve(id+'-tangent',frame,[[-1,v+slope*(-1-at)],[1,v+slope*(1-at)]],{color:P.muted,width:1});board.circle(id+'-dot',frame.x(at),frame.y(v),4,color);board.text(id+'-slope','斜率 '+VisualBook.formatNumber(slope,{precision:2}),sx+sw,y-14,{size:14,color,anchor:'end'});return {x:at,value:v,slope};}
 const s1=slice('slice1',sy,[2*b*b,0,1],P.blue,'固定 x₂；沿 x₁',g[0],a);const s2=slice('slice2',sy+sh+55,[a*a,0,2],P.orange,'固定 x₁；沿 x₂',g[1],b);
 board.text('result','∇f = ['+VisualBook.formatNumber(g[0],{precision:2})+', '+VisualBook.formatNumber(g[1],{precision:2})+']',mobile?38:370,mobile?height-20:height-24,{size:18,color:P.ink});
 return {point:[a,b],value:a*a+2*b*b,gradient:g,endpoint:[a+g[0],b+g[1]],slices:[s1,s2],contours:[1,2,3,4],example:'supplementary analytic quadratic; no training'};
}

function draw(input){
 const {board,width,height,params}=input;const P=VisualBook.palette;const x=params.x;const mobile=width<600;const ax=mobile?30:80,bx=width/2,cx=width-(mobile?34:80);const cy=mobile?155:120,uy=cy-64,dy=cy+64;const num=v=>VisualBook.formatNumber(v,{precision:2});
 board.text('input-name','x',ax,cy-14,{anchor:'middle',size:18,color:P.ink});board.circle('input',ax,cy,4,P.ink);board.text('input-value',num(x),ax,cy+24,{anchor:'middle',size:16,color:P.ink});
 board.text('upper-name','u₁ = x²',bx,uy-16,{anchor:'middle',size:16,color:P.blue});board.circle('upper',bx,uy,4,P.blue);board.text('upper-value',num(x*x),bx,uy+24,{anchor:'middle',size:16,color:P.blue});
 board.text('lower-name','u₂ = −x',bx,dy-16,{anchor:'middle',size:16,color:P.orange});board.circle('lower',bx,dy,4,P.orange);board.text('lower-value',num(-x),bx,dy+24,{anchor:'middle',size:16,color:P.orange});
 board.text('output-name','y',cx,cy-14,{anchor:'middle',size:18,color:P.ink});board.circle('output',cx,cy,4,P.ink);board.text('output-value',num(x*x-x),cx,cy+24,{anchor:'middle',size:16,color:P.ink});
 function edge(id,x1,y1,x2,y2,color,label){board.line(id,x1,y1,x2,y2,color,1.5,0.65);const dx=x2-x1,dd=y2-y1,len=Math.hypot(dx,dd);const tx=x2-dx/len*9,ty=y2-dd/len*9;board.path(id+'-head',[[tx-dx/len*6-dd/len*3,ty-dd/len*6+dx/len*3],[tx,ty],[tx-dx/len*6+dd/len*3,ty-dd/len*6-dx/len*3]],{color,width:1.5});board.text(id+'-gain',label,(x1+x2)/2,(y1+y2)/2+(y2<y1?-15:23),{anchor:'middle',size:14,color});}
 edge('x-u1',ax+7,cy-4,bx-7,uy+4,P.blue,'× '+num(2*x));edge('u1-y',bx+7,uy+4,cx-7,cy-4,P.blue,'× 1');edge('x-u2',ax+7,cy+4,bx-7,dy-4,P.orange,'× (−1)');edge('u2-y',bx+7,dy-4,cx-7,cy+4,P.orange,'× 1');
 const by=mobile?290:252;board.text('path1','上路：'+num(2*x)+' × 1 = '+num(2*x),24,by,{size:15,color:P.blue});board.text('path2','下路：−1 × 1 = −1',mobile?24:width/2, mobile?by+28:by,{size:15,color:P.orange});
 board.text('sum','dy/dx = '+num(2*x)+' − 1 = '+num(2*x-1),24,height-22,{size:18,color:P.ink});
 return {x,u1:x*x,u2:-x,y:x*x-x,localDerivatives:{u1_x:2*x,u2_x:-1,y_u1:1,y_u2:1},pathContributions:[2*x,-1],derivative:2*x-1,example:'supplementary two-path function; analytic values'};
}
